type ProductSeed = Omit<Product, "id" | "status" | "is_sample" | "sku" | "price_is_sample" | "pricing_mode" | "price_php" | "price_basis" | "warranty_terms"> &
  Partial<Pick<Product, "pricing_mode" | "price_php" | "price_basis" | "price_is_sample" | "warranty_terms">>;

const product = (n: number, p: ProductSeed): Product => ({
  id: id(0x100 + n),
  sku: null,
  status: "published",
  is_sample: true,
  pricing_mode: "quote",
  price_php: null,
  price_basis: null,
  price_is_sample: false,
  warranty_terms: null,
  ...p,
});

